// Connected initializer/geometry/scan; supplied NAND, heap, format and time.
//@category SpellboundOS
import ghidra.app.script.GhidraScript;
import ghidra.app.emulator.EmulatorHelper;
import com.google.gson.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

public class ValidateEftlInitialize extends GhidraScript {
    private static final String CONFIG="{\"initialize\":2160075416,\"geometry\":2160075872,\"resume\":2160074122,\"find\":2160235640,\"ioctl\":2160236108,\"format\":2160076890,\"alloc\":2160173832,\"free\":2160173842,\"memset\":2160254996,\"clock\":2160157742,\"millis\":2160161236,\"assertion\":2160157974,\"bad\":2160077016,\"erase\":2160076842,\"oob\":2160076720,\"logger\":2160184698,\"lazy\":2160210390,\"lazy_logger\":2160184464,\"ranges\":[[2160074122,352],[2160073226,80],[2160075416,456],[2160075872,372],[2160076890,126],[2160210390,124]],\"logs\":{\"2160279728\":\"bad_block\",\"2160279760\":\"oob_read_error\",\"2160279400\":\"checksum_error\",\"2160280180\":\"geometry_summary\",\"2160280220\":\"format_error\",\"2160280248\":\"capacity_summary\",\"2160280292\":\"block_summary\",\"2160310936\":\"eftl_ready\"},\"guards\":[{\"address\":2160074122,\"size\":352,\"sha256\":\"627b6414298e79230eb17db6291f05d99573c740082fe86d720f61b914e1b2f4\"},{\"address\":2160073226,\"size\":80,\"sha256\":\"eae8f359810bcc1382c84110bb2c4b4ee0b893a9a279491618fd314994a019be\"},{\"address\":2160075416,\"size\":456,\"sha256\":\"2f0cc83e90ee2e8654f2b2e173599b9fb152246b2cb83ecbfdb93d56b939395c\"},{\"address\":2160075872,\"size\":372,\"sha256\":\"c635128654def095216de8bb7d3b428fb174fa17b10b2a38e042882715ea6cc6\"},{\"address\":2160076890,\"size\":126,\"sha256\":\"4f145deeed5f93d95ba09222107892b24d164c7b65e7b6c675f430dcc227952e\"},{\"address\":2160210390,\"size\":124,\"sha256\":\"8c585a2df07a652d6800f435a03991ea412a1ea0a5813565e6459a1828f8da6d\"}]}";
    private static final long END=0x70000000L,CONTEXT=0x80de5fb8L,NAND=0x81230000L,HEAP=0x81400000L;
    private static final long[] OLD={0x81240000L,0x81241000L,0x81242000L};
    private static class Allocation {long pointer;int size;boolean active=true;Allocation(long p,int n){pointer=p;size=n;}}
    private JsonObject cfg,c,stopped;private JsonArray actions;private int steps,ordinal,ticks;private ArrayList<Allocation> allocations;
    private long a(String k){return cfg.get(k).getAsLong();}
    private long r(EmulatorHelper e,int i){return e.readRegister("a"+i).longValue()&0xffffffffL;}
    private void put(EmulatorHelper e,long at,int n,long v){e.writeMemoryValue(toAddr(at),n,v);}
    private byte[] mem(EmulatorHelper e,long at,int n){return n==0?new byte[0]:e.readMemory(toAddr(at),n);}
    private long value(EmulatorHelper e,long at,int n){byte[] b=mem(e,at,n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}
    private String hash(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
    private void ret(EmulatorHelper e,long v){e.writeRegister("a0",v&0xffffffffL);e.writeRegister(e.getPCRegister(),e.readRegister("ra"));}
    private Allocation allocation(long p){for(var x:allocations)if(x.pointer==p)return x;throw new IllegalStateException("Unknown allocation "+Long.toHexString(p));}
    private byte[] record(JsonObject b){int logical=b.get("logical").getAsInt(),tag=b.get("tag").getAsInt();byte[] data={(byte)logical,(byte)(logical>>8),(byte)tag,0};data[3]=(byte)((data[0]&255)+(data[1]&255)+tag+(b.get("corrupt").getAsBoolean()?1:0));return data;}
    private void seedAllocation(EmulatorHelper e,long p,int n,byte fill){if(n<1||n>512)throw new IllegalStateException("Allocation bound");byte[] b=new byte[n+32];Arrays.fill(b,0,n,fill);Arrays.fill(b,n,n+32,(byte)0xa5);e.writeMemory(toAddr(p),b);allocations.add(new Allocation(p,n));}
    private boolean writable(long p,int n){if(p>=0x81000000L&&p+n<=0x81001000L||p>=CONTEXT&&p+n<=CONTEXT+64)return true;for(var x:allocations)if(x.active&&p>=x.pointer&&p+n<=x.pointer+x.size)return true;return false;}
    private void abi(EmulatorHelper e){if(e.readRegister("sp").longValue()!=0x81001000L)throw new IllegalStateException("Stack mismatch");for(int i=0;i<12;i++)if(e.readRegister("s"+i).longValue()!=0x45670000L+i)throw new IllegalStateException("Saved register mismatch");}
    private void entry(EmulatorHelper e,long start,long... args)throws Exception {
        stopped=null;e.writeRegister("ra",END);for(int i=0;i<args.length;i++)e.writeRegister("a"+i,args[i]);e.writeRegister(e.getPCRegister(),start);long pc;
        while((pc=e.getExecutionAddress().getOffset())!=END){
            if(++steps>100000)throw new IllegalStateException("Execution bound");
            if(pc==a("resume")){if(r(e,0)!=CONTEXT||r(e,1)>1)throw new IllegalStateException("Scan arguments");actions.add("scan:"+r(e,1));}
            if(pc==a("find")){if(r(e,0)!=0x80c343e0L)throw new IllegalStateException("NAND lookup name");boolean ok=c.get("find_ok").getAsBoolean();actions.add("find:eftl:"+(ok?1:0));ret(e,ok?NAND:0);continue;}
            if(pc==a("ioctl")){if(r(e,0)!=NAND)throw new IllegalStateException("NAND ioctl handle");int query=(int)r(e,1),status=c.get("ioctl_status").getAsInt();long out=r(e,2);if(query==10||query==12){if(!c.get("format_native").getAsBoolean()||!writable(out,4))throw new IllegalStateException("Format ioctl arguments");long index=value(e,out,4);if(index>=value(e,CONTEXT+16,4)||index>=8)throw new IllegalStateException("Format block bound");JsonObject block=c.getAsJsonArray("blocks").get((int)index).getAsJsonObject();status=block.get(query==10?"bad":"erase").getAsInt();actions.add((query==10?"format_bad:":"format_erase:")+index+":"+status);ret(e,status);continue;}String key=switch(query){case 1->"pages";case 2->"page_size";case 3->"pages_per_block";case 18->"spare";case 19->"ecc_total";case 20->"ecc_unit";case 21->"positions";default->throw new IllegalStateException("Unexpected ioctl");};int n=query==21?16:4;if(!writable(out,n))throw new IllegalStateException("Ioctl output");actions.add("ioctl:"+query+":"+status);if(query==21){for(int i=0;i<4;i++)put(e,out+4*i,4,c.getAsJsonArray(key).get(i).getAsLong());}else put(e,out,4,c.get(key).getAsLong());ret(e,status);continue;}
            if(pc==a("format")){if(r(e,0)!=CONTEXT||r(e,1)!=c.get("format_kind").getAsLong())throw new IllegalStateException("Format arguments");if(c.get("format_native").getAsBoolean())actions.add("format_native:"+r(e,1));else{int status=c.get("format_status").getAsInt();actions.add("format:"+r(e,1)+":"+status);ret(e,status);continue;}}
            if(pc==a("alloc")){int n=(int)r(e,0);if(++ordinal>8)throw new IllegalStateException("Allocation count bound");long p=ordinal==c.get("alloc_fail_at").getAsInt()?0:HEAP+(ordinal-1)*4096L;actions.add("alloc:"+n+":"+p);if(p!=0)seedAllocation(e,p,n,(byte)0xa5);ret(e,p);continue;}
            if(pc==a("free")){var x=allocation(r(e,0));if(!x.active)throw new IllegalStateException("Double free");x.active=false;actions.add("free:"+r(e,0));ret(e,0);continue;}
            if(pc==a("memset")){long out=r(e,0);int fill=(int)(r(e,1)&255),n=(int)r(e,2);if(n<0||n>512)throw new IllegalStateException("Fill bound");actions.add("fill:"+out+":"+fill+":"+n);if(out==0){stopped=new JsonObject();stopped.addProperty("kind","null_memset");stopped.addProperty("size",n);stopped.addProperty("fill",fill);return;}if(!writable(out,n))throw new IllegalStateException("Fill output");byte[] b=new byte[n];Arrays.fill(b,(byte)fill);if(n>0)e.writeMemory(toAddr(out),b);ret(e,out);continue;}
            if(pc==a("assertion")){if(r(e,1)!=0x80c34480L)throw new IllegalStateException("Unexpected assertion owner");stopped=new JsonObject();stopped.addProperty("kind","assertion");stopped.addProperty("line",r(e,2));return;}
            if(pc==a("clock")){ticks++;actions.add("clock:"+ticks*1000);e.writeRegister("a1",0);ret(e,ticks*1000);continue;}
            if(pc==a("millis")){if(r(e,0)!=ticks*1000||r(e,1)!=0)throw new IllegalStateException("Clock conversion");actions.add("millis:"+ticks*1000+":"+ticks*10);ret(e,ticks*10);continue;}
            if(pc==a("bad")||pc==a("erase")||pc==a("oob")){
                if(r(e,0)!=CONTEXT)throw new IllegalStateException("Block service context");boolean oob=pc==a("oob");long index=r(e,1),pages=value(e,CONTEXT+8,4);if(oob){if(pages==0||index%pages!=0)throw new IllegalStateException("OOB page");index/=pages;}if(index>=value(e,CONTEXT+16,4)||index>=8)throw new IllegalStateException("Block bound");JsonObject block=c.getAsJsonArray("blocks").get((int)index).getAsJsonObject();String key=oob?"read":pc==a("bad")?"bad":"erase";int result=block.get(key).getAsInt();
                if(oob){byte[] data=record(block);if(!writable(r(e,2),4))throw new IllegalStateException("OOB output");actions.add("oob:"+r(e,1)+":"+result+":"+HexFormat.of().formatHex(data));if(result==0)e.writeMemory(toAddr(r(e,2)),data);}else actions.add(key+":"+index+":"+result);ret(e,result);continue;
            }
            if(pc==a("logger")||pc==a("lazy_logger")){JsonElement tag=cfg.getAsJsonObject("logs").get(Long.toString(r(e,3)));if(tag==null)throw new IllegalStateException("Unexpected initialization log "+Long.toHexString(r(e,3)));actions.add("log:"+tag.getAsString());ret(e,0);continue;}
            boolean allowed=false;for(JsonElement span:cfg.getAsJsonArray("ranges")){long first=span.getAsJsonArray().get(0).getAsLong(),n=span.getAsJsonArray().get(1).getAsLong();if(pc>=first&&pc<first+n){allowed=true;break;}}
            if(!allowed)throw new IllegalStateException(c.get("name")+" escaped at "+Long.toHexString(pc));if(!e.step(monitor))throw new IllegalStateException(c.get("name")+" "+e.getLastError());
        }abi(e);
    }
    private JsonObject snapshot(EmulatorHelper e)throws Exception {
        JsonObject row=new JsonObject();row.add("returned",stopped==null&&!c.get("mode").getAsString().equals("lazy")?new JsonPrimitive(r(e,0)):JsonNull.INSTANCE);row.add("stopped",stopped==null?JsonNull.INSTANCE:stopped.deepCopy());byte[] context=mem(e,CONTEXT,64);row.addProperty("context_sha256",hash(context));row.addProperty("eftl_ready",value(e,0x80d81ea2L,1));row.addProperty("capacity_word",value(e,0x80d80fd4L,4));row.addProperty("block_word",value(e,0x80d80fd8L,4));row.addProperty("context_hex",HexFormat.of().formatHex(context));
        for(Object[] f:new Object[][]{{"marker",4,1},{"read_behavior",5,1},{"page_size",12,4},{"pages_per_block",8,4},{"block_count",16,4},{"base_page",24,4}})row.addProperty((String)f[0],value(e,CONTEXT+(int)f[1],(int)f[2]));
        JsonArray pointers=new JsonArray(),counters=new JsonArray();for(int i=0;i<3;i++){pointers.add(value(e,CONTEXT+44+4*i,4));counters.add(value(e,CONTEXT+56+2*i,2));}row.add("pointers",pointers);row.add("counters",counters);JsonArray heap=new JsonArray();for(var x:allocations){JsonObject b=new JsonObject();b.addProperty("pointer",x.pointer);b.addProperty("size",x.size);b.addProperty("active",x.active);b.addProperty("sha256",hash(mem(e,x.pointer,x.size)));heap.add(b);}row.add("allocations",heap);return row;
    }
    private JsonObject execute(JsonObject input)throws Exception {
        c=input;steps=0;ordinal=0;ticks=0;allocations=new ArrayList<>();actions=new JsonArray();EmulatorHelper e=new EmulatorHelper(currentProgram);
        try{
            byte[] stack=new byte[4096];Arrays.fill(stack,(byte)0xa5);e.writeMemory(toAddr(0x81000000L),stack);e.writeRegister("sp",0x81001000L);for(int i=0;i<12;i++)e.writeRegister("s"+i,0x45670000L+i);
            put(e,0x80d81ea2L,1,c.get("eftl_ready").getAsBoolean()?1:0);put(e,0x80d80fd4L,4,0x7fffffffL);put(e,0x80d80fd8L,4,0x20000L);byte[] context=new byte[96];Arrays.fill(context,64,96,(byte)0xa5);e.writeMemory(toAddr(CONTEXT),context);put(e,CONTEXT+4,1,c.get("marker").getAsLong());put(e,CONTEXT,4,c.get("handle_present").getAsBoolean()?NAND:0);
            byte[] nand=new byte[64];Arrays.fill(nand,(byte)0xa5);e.writeMemory(toAddr(NAND),nand);put(e,NAND+48,4,c.get("partition_offset").getAsLong());nand=mem(e,NAND,64);
            for(int i=0;i<3;i++)if((c.get("old_mask").getAsInt()&(1<<i))!=0){seedAllocation(e,OLD[i],new int[]{4,8,48}[i],(byte)0x55);put(e,CONTEXT+44+4*i,4,OLD[i]);}
            JsonArray rows=new JsonArray();for(int iteration=0;iteration<c.get("repeat").getAsInt();iteration++){if(c.get("mode").getAsString().equals("geometry"))entry(e,a("geometry"),CONTEXT);else if(c.get("mode").getAsString().equals("lazy"))entry(e,a("lazy"));else entry(e,a("initialize"),CONTEXT,c.get("force").getAsLong(),c.get("format_kind").getAsLong());rows.add(snapshot(e));if(stopped!=null)break;}
            byte[] guard=new byte[32];Arrays.fill(guard,(byte)0xa5);if(!Arrays.equals(guard,mem(e,CONTEXT+64,32))||!Arrays.equals(nand,mem(e,NAND,64)))throw new IllegalStateException("Context/NAND input guard");for(var x:allocations)if(!Arrays.equals(guard,mem(e,x.pointer+x.size,32)))throw new IllegalStateException("Heap guard");
            JsonObject observed=new JsonObject();observed.add("actions",actions);observed.add("rows",rows);if(!observed.equals(c.getAsJsonObject("expected"))){Files.writeString(Path.of("firmware/eftl-initialize-mismatch.json"),observed.toString());throw new IllegalStateException("Mismatch "+c.get("name"));}
            JsonObject result=new JsonObject();result.addProperty("name",c.get("name").getAsString());result.addProperty("steps",steps);result.add("observed",observed);return result;
        }finally{e.dispose();}
    }
    public void run()throws Exception {
        if(getScriptArgs().length!=2)throw new IllegalArgumentException("vectors report");cfg=JsonParser.parseString(CONFIG).getAsJsonObject();for(JsonElement item:cfg.getAsJsonArray("guards")){JsonObject g=item.getAsJsonObject();byte[] b=new byte[g.get("size").getAsInt()];currentProgram.getMemory().getBytes(toAddr(g.get("address").getAsLong()),b);if(!hash(b).equals(g.get("sha256").getAsString()))throw new IllegalStateException("Unrecognized initialization code");}
        JsonObject input=JsonParser.parseString(Files.readString(Path.of(getScriptArgs()[0]))).getAsJsonObject();if(input.get("schema").getAsInt()!=1||input.getAsJsonArray("cases").size()>64)throw new IllegalArgumentException("Vector bound");JsonArray rows=new JsonArray();for(JsonElement item:input.getAsJsonArray("cases"))rows.add(execute(item.getAsJsonObject()));JsonObject report=new JsonObject();report.addProperty("hardware_execution",false);report.addProperty("case_count",rows.size());report.addProperty("bound_per_case",100000);report.add("cases",rows);Files.writeString(Path.of(getScriptArgs()[1]),new GsonBuilder().setPrettyPrinting().serializeNulls().create().toJson(report)+"\n");println("EFTL_INITIALIZE_VALIDATION cases="+rows.size());
    }
}
